func TestAdd(t *testing.T) {
	if add(2, 3) != 5 {
		t.Fatalf("add(2, 3) = %d, want 5", add(2, 3))
	}
}

func TestClamp(t *testing.T) {
	tests := []struct {
		name   string
		value  int
		lower  int
		upper  int
		want   int
	}{
		{"within range", 5, 0, 10, 5},
		{"below lower", -3, 0, 10, 0},
		{"above upper", 15, 0, 10, 10},
		{"at lower", 0, 0, 10, 0},
		{"at upper", 10, 0, 10, 10},
		{"single point range", 7, 7, 7, 7},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := clamp(tt.value, tt.lower, tt.upper)
			if got != tt.want {
				t.Fatalf("clamp(%d, %d, %d) = %d, want %d", tt.value, tt.lower, tt.upper, got, tt.want)
			}
		})
	}
}

